-- Dalilak – complete database setup. GENERATED by `npm run db:bundle`; do not edit by hand.
-- Run once on a NEW Supabase project (SQL Editor → New query → paste → Run).

-- ===== 20261126000001_schema.sql =====
-- Dalilak – 0001 schema: types, tables, indexes, triggers.
-- Supabase installs extensions in the "extensions" schema.

create schema if not exists extensions;
create extension if not exists pg_trgm  with schema extensions;
create extension if not exists unaccent with schema extensions;

-- ---------------------------------------------------------------------------
-- Text normalisation used for search (Latin accents + Arabic letter variants).
-- unaccent() is not immutable, so we wrap it with a fixed dictionary.
-- ---------------------------------------------------------------------------
create or replace function public.normalize_text(t text)
returns text
language sql immutable parallel safe
set search_path = ''
as $$
  select regexp_replace(
           translate(
             lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(t, ''))),
             'أإآٱىةـ',        -- alef variants, alef maqsura, ta marbuta, tatweel
             'اااايه'           -- (tatweel has no counterpart, so it is removed)
           ),
           '[ً-ْ]', '', 'g')  -- Arabic diacritics (tashkeel)
$$;

-- URL slug: latin letters and digits only. Arabic-only names get an empty slug
-- and the caller falls back to "listing-<id>".
create or replace function public.slugify(t text)
returns text
language sql immutable parallel safe
set search_path = ''
as $$
  select trim(both '-' from regexp_replace(
           lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(t, ''))),
           '[^a-z0-9]+', '-', 'g'))
$$;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.listing_status as enum ('active', 'pending', 'hidden');
create type public.listing_source as enum ('google_maps', 'owner', 'admin');
create type public.user_role      as enum ('user', 'owner', 'admin');
create type public.review_status  as enum ('visible', 'hidden');
create type public.reporter_role  as enum ('user', 'owner', 'visitor');
create type public.report_kind    as enum ('wrong_info', 'closed', 'abusive_review', 'other', 'owner_complaint');
create type public.report_status  as enum ('new', 'in_progress', 'resolved');
create type public.request_status as enum ('pending', 'approved', 'rejected');
create type public.photo_kind     as enum ('logo', 'gallery');
create type public.sub_store      as enum ('stripe', 'google_play');
create type public.sub_status     as enum ('trialing', 'active', 'past_due', 'canceled', 'expired');
create type public.event_kind     as enum ('view', 'call', 'directions', 'website', 'share');

-- ---------------------------------------------------------------------------
-- Lookup tables
-- ---------------------------------------------------------------------------
create table public.categories (
  slug               text primary key,
  name_ar            text not null,
  name_fr            text not null,
  name_nl            text not null,
  name_en            text not null,
  icon               text,
  sort_order         int  not null default 0,
  requires_languages boolean not null default false
);

create table public.provinces (
  slug       text primary key,
  name_ar    text not null,
  name_fr    text not null,
  name_nl    text not null,
  name_en    text not null,
  is_launch  boolean not null default false,
  sort_order int not null default 0
);

-- ---------------------------------------------------------------------------
-- Profiles (one per auth user)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id             uuid primary key references auth.users on delete cascade,
  display_name   text check (char_length(display_name) <= 60),
  role           public.user_role not null default 'user',
  preferred_lang text not null default 'ar' check (preferred_lang in ('ar', 'fr', 'nl', 'en')),
  created_at     timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Listings
-- Free listing shows name, address, phone, category (+ Google rating).
-- Premium adds logo, gallery (max 8), description, offer line, website, badge.
-- Listings are never deleted when premium ends; only the extras are hidden.
-- ---------------------------------------------------------------------------
create table public.listings (
  id                bigint generated by default as identity primary key,
  slug              text not null unique,
  name              text not null check (char_length(name) between 2 and 200),
  category          text not null references public.categories on update cascade,
  type_label        text,
  province          text not null references public.provinces on update cascade,
  city              text,
  address           text,
  phone             text,
  website           text,
  rating_google     numeric(2,1) check (rating_google between 0 and 5),
  reviews_google    int not null default 0 check (reviews_google >= 0),
  lat               double precision,
  lng               double precision,
  languages         text[] not null default '{}',
  language_verified boolean not null default true,
  status            public.listing_status not null default 'pending',
  is_premium        boolean not null default false,
  premium_until     timestamptz,             -- null + is_premium = no expiry (granted by admin)
  is_verified       boolean not null default false,
  logo_path         text,                    -- storage path in bucket listing-photos
  description       jsonb not null default '{}'::jsonb,   -- {"ar": "...", "fr": "..."}
  offer_text        jsonb not null default '{}'::jsonb,
  owner_id          uuid references auth.users on delete set null,
  source            public.listing_source not null,
  app_rating_avg    numeric(3,2),
  app_reviews_count int not null default 0,
  search_doc        text generated always as (
                      public.normalize_text(coalesce(name, '') || ' ' || coalesce(city, '') || ' ' ||
                                            coalesce(type_label, '') || ' ' || coalesce(address, ''))
                    ) stored,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index listings_filter_idx  on public.listings (status, category, province);
create index listings_premium_idx on public.listings (is_premium, premium_until) where is_premium;
create index listings_owner_idx   on public.listings (owner_id) where owner_id is not null;
create index listings_search_idx  on public.listings using gin (search_doc extensions.gin_trgm_ops);

-- Owner photos (premium only). Admin approves before they show.
create table public.listing_photos (
  id           bigint generated always as identity primary key,
  listing_id   bigint not null references public.listings on delete cascade,
  kind         public.photo_kind not null default 'gallery',
  storage_path text not null unique,
  sort_order   int not null default 0,
  status       public.request_status not null default 'pending',
  created_at   timestamptz not null default now()
);
create index on public.listing_photos (listing_id, kind, status);

-- Owner edits wait for admin approval.
create table public.listing_edits (
  id         bigint generated always as identity primary key,
  listing_id bigint not null references public.listings on delete cascade,
  owner_id   uuid not null default auth.uid() references auth.users on delete cascade,
  changes    jsonb not null,
  status     public.request_status not null default 'pending',
  admin_note text,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
create index on public.listing_edits (status, created_at);

create table public.favorites (
  user_id    uuid   not null default auth.uid() references auth.users on delete cascade,
  listing_id bigint not null references public.listings on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, listing_id)
);

create table public.reviews (
  id               bigint generated always as identity primary key,
  listing_id       bigint not null references public.listings on delete cascade,
  user_id          uuid   not null default auth.uid() references auth.users on delete cascade,
  stars            smallint not null check (stars between 1 and 5),
  text             text check (char_length(text) <= 2000),
  status           public.review_status not null default 'visible',
  owner_reply      text check (char_length(owner_reply) <= 1000),
  owner_replied_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (listing_id, user_id)
);

create table public.reports (
  id            bigint generated always as identity primary key,
  listing_id    bigint references public.listings on delete set null,
  review_id     bigint references public.reviews  on delete set null,
  reporter_id   uuid   references auth.users      on delete set null,
  reporter_role public.reporter_role not null default 'visitor',
  kind          public.report_kind not null,
  message       text not null check (char_length(message) between 3 and 3000),
  contact_email text check (contact_email is null or contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  status        public.report_status not null default 'new',
  admin_note    text,
  created_at    timestamptz not null default now()
);
create index on public.reports (status, created_at);

create table public.claims (
  id         bigint generated always as identity primary key,
  listing_id bigint not null references public.listings on delete cascade,
  user_id    uuid   not null default auth.uid() references auth.users on delete cascade,
  proof_note text check (char_length(proof_note) <= 2000),
  status     public.request_status not null default 'pending',
  admin_note text,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
create unique index claims_one_pending on public.claims (listing_id, user_id) where status = 'pending';

create table public.subscriptions (
  id                     bigint generated always as identity primary key,
  owner_id               uuid   not null references auth.users on delete cascade,
  listing_id             bigint not null references public.listings on delete cascade,
  plan                   text not null default 'premium_monthly',
  status                 public.sub_status not null,
  current_period_end     timestamptz,
  cancel_at_period_end   boolean not null default false,
  store                  public.sub_store not null default 'stripe',
  store_purchase_token   text,
  stripe_customer_id     text,
  stripe_subscription_id text unique,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
create index on public.subscriptions (listing_id);

-- Anonymous statistics: no user id, no IP, no cookies.
create table public.listing_events (
  id         bigint generated always as identity primary key,
  listing_id bigint not null references public.listings on delete cascade,
  kind       public.event_kind not null,
  created_at timestamptz not null default now()
);
create index on public.listing_events (listing_id, kind, created_at);

create table public.search_log (
  id         bigint generated always as identity primary key,
  query      text check (char_length(query) <= 100),
  category   text,
  province   text,
  results    int,
  created_at timestamptz not null default now()
);

create table public.push_tokens (
  user_id    uuid not null default auth.uid() references auth.users on delete cascade,
  token      text not null,
  platform   text not null default 'android' check (platform in ('android', 'ios', 'web')),
  created_at timestamptz not null default now(),
  primary key (user_id, token)
);

create table public.short_links (
  code       text primary key check (code ~ '^[a-z0-9-]{2,40}$'),
  listing_id bigint not null references public.listings on delete cascade
);

-- ---------------------------------------------------------------------------
-- Generic triggers
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger listings_touch      before update on public.listings      for each row execute function public.touch_updated_at();
create trigger reviews_touch       before update on public.reviews       for each row execute function public.touch_updated_at();
create trigger subscriptions_touch before update on public.subscriptions for each row execute function public.touch_updated_at();

-- New auth user -> profile row.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, display_name, preferred_lang)
  values (
    new.id,
    nullif(left(new.raw_user_meta_data ->> 'display_name', 60), ''),
    case when new.raw_user_meta_data ->> 'lang' in ('ar', 'fr', 'nl', 'en')
         then new.raw_user_meta_data ->> 'lang' else 'ar' end
  )
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Keep app rating columns in sync with visible reviews.
create or replace function public.refresh_listing_rating()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  lid bigint := coalesce(new.listing_id, old.listing_id);
begin
  update public.listings l
     set app_rating_avg    = s.avg_stars,
         app_reviews_count = s.n
    from (select round(avg(stars)::numeric, 2) as avg_stars, count(*)::int as n
            from public.reviews where listing_id = lid and status = 'visible') s
   where l.id = lid;
  return null;
end $$;

create trigger reviews_rating_sync
  after insert or update of stars, status or delete on public.reviews
  for each row execute function public.refresh_listing_rating();

-- Max 1 logo + 8 gallery photos per listing (pending + approved).
create or replace function public.check_photo_limit()
returns trigger language plpgsql set search_path = '' as $$
declare
  n int;
begin
  select count(*) into n from public.listing_photos
   where listing_id = new.listing_id and kind = new.kind and status <> 'rejected';
  if new.kind = 'gallery' and n >= 8 then
    raise exception 'photo_limit: max 8 gallery photos' using errcode = 'check_violation';
  elsif new.kind = 'logo' and n >= 1 then
    raise exception 'photo_limit: max 1 logo' using errcode = 'check_violation';
  end if;
  return new;
end $$;

create trigger listing_photos_limit
  before insert on public.listing_photos
  for each row execute function public.check_photo_limit();

-- ===== 20261126000002_rls.sql =====
-- Dalilak – 0002 row level security and grants.
-- Principle: tables are read through RLS; anything that needs extra checks
-- (status changes, approvals, owner replies) goes through SECURITY DEFINER
-- functions in 0003. Admin actions always go through those functions.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
$$;

-- Computed column: usable from the API as  select=*,premium_active
create or replace function public.premium_active(l public.listings)
returns boolean language sql stable set search_path = '' as $$
  select l.is_premium and (l.premium_until is null or l.premium_until > now())
$$;

create or replace function public.owns_listing(p_listing_id bigint)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.listings where id = p_listing_id and owner_id = auth.uid())
$$;

create or replace function public.listing_premium(p_listing_id bigint)
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select public.premium_active(l) from public.listings l where l.id = p_listing_id), false)
$$;

-- ---------------------------------------------------------------------------
-- Grants: start from nothing, then open exactly what the app needs.
-- ---------------------------------------------------------------------------
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

grant usage on schema public to anon, authenticated;

grant select on public.categories, public.provinces, public.listings,
                public.listing_photos, public.reviews, public.short_links
  to anon, authenticated;

grant insert (listing_id, review_id, kind, message, contact_email) on public.reports to anon, authenticated;

grant select, insert, update, delete on public.categories, public.provinces, public.short_links to authenticated; -- admin only (RLS)
grant select, update (display_name, preferred_lang)                  on public.profiles       to authenticated;
grant select, delete, insert (user_id, listing_id)                   on public.favorites      to authenticated;
grant delete, insert (listing_id, user_id, stars, text),
              update (stars, text)                                   on public.reviews        to authenticated;
grant select                                                         on public.reports        to authenticated;
grant select, insert (listing_id, user_id, proof_note)               on public.claims         to authenticated;
grant select, insert (listing_id, owner_id, changes)                 on public.listing_edits  to authenticated;
grant delete, insert (listing_id, kind, storage_path, sort_order)    on public.listing_photos to authenticated;
grant select                                                         on public.subscriptions  to authenticated;
grant select, delete, insert (user_id, token, platform)              on public.push_tokens    to authenticated;
-- listing_events / search_log: written only through track_event() / log_search().

-- Every table has RLS on.
alter table public.categories     enable row level security;
alter table public.provinces      enable row level security;
alter table public.profiles       enable row level security;
alter table public.listings       enable row level security;
alter table public.listing_photos enable row level security;
alter table public.listing_edits  enable row level security;
alter table public.favorites      enable row level security;
alter table public.reviews        enable row level security;
alter table public.reports        enable row level security;
alter table public.claims         enable row level security;
alter table public.subscriptions  enable row level security;
alter table public.listing_events enable row level security;
alter table public.search_log     enable row level security;
alter table public.push_tokens    enable row level security;
alter table public.short_links    enable row level security;

-- ---------------------------------------------------------------------------
-- Lookups: everyone reads, admin writes.
-- ---------------------------------------------------------------------------
create policy categories_read  on public.categories  for select using (true);
create policy categories_admin on public.categories  for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy provinces_read   on public.provinces   for select using (true);
create policy provinces_admin  on public.provinces   for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy short_links_read  on public.short_links for select using (true);
create policy short_links_admin on public.short_links for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Profiles: own row (admin sees all). Role cannot be changed by the user:
-- only display_name / preferred_lang are granted for update.
-- ---------------------------------------------------------------------------
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy profiles_update on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

-- ---------------------------------------------------------------------------
-- Listings: visitors see active ones; owners also see their own pending /
-- hidden ones; admin sees all. No direct writes (see submit_listing(),
-- approve_*() and listing_edits).
-- ---------------------------------------------------------------------------
create policy listings_select on public.listings for select
  using (status = 'active' or owner_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- Photos: public sees approved photos of listings with active premium.
-- Owner of a premium listing may add photos (pending) and delete own photos.
-- ---------------------------------------------------------------------------
create policy photos_select on public.listing_photos for select
  using (
    (status = 'approved' and public.listing_premium(listing_id))
    or public.owns_listing(listing_id)
    or public.is_admin()
  );
create policy photos_insert on public.listing_photos for insert to authenticated
  with check (
    status = 'pending'
    and public.owns_listing(listing_id)
    and public.listing_premium(listing_id)
    and storage_path like listing_id::text || '/%'
  );
create policy photos_delete on public.listing_photos for delete to authenticated
  using (public.owns_listing(listing_id) or public.is_admin());

-- ---------------------------------------------------------------------------
-- Owner edit requests
-- ---------------------------------------------------------------------------
create policy edits_select on public.listing_edits for select to authenticated
  using (owner_id = auth.uid() or public.is_admin());
create policy edits_insert on public.listing_edits for insert to authenticated
  with check (
    owner_id = auth.uid()
    and status = 'pending'
    and admin_note is null
    and decided_at is null
    and public.owns_listing(listing_id)
  );

-- ---------------------------------------------------------------------------
-- Favorites ("محفوظاتي")
-- ---------------------------------------------------------------------------
create policy favorites_own on public.favorites for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Reviews: everyone reads visible ones; author sees own; one per listing.
-- Owner reply and hiding go through functions.
-- ---------------------------------------------------------------------------
create policy reviews_select on public.reviews for select
  using (status = 'visible' or user_id = auth.uid() or public.is_admin());
create policy reviews_insert on public.reviews for insert to authenticated
  with check (
    user_id = auth.uid()
    and status = 'visible'
    and owner_reply is null
    and exists (select 1 from public.listings l where l.id = listing_id and l.status = 'active')
    and not public.owns_listing(listing_id)          -- no self-reviews
  );
create policy reviews_update on public.reviews for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy reviews_delete on public.reviews for delete to authenticated
  using (user_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- Reports (complaints box): anyone can send; reporter fields are filled by
-- a trigger so nobody can spoof them. Reporter sees own; admin sees all.
-- ---------------------------------------------------------------------------
create policy reports_insert on public.reports for insert
  with check (status = 'new' and admin_note is null);
create policy reports_select on public.reports for select to authenticated
  using (reporter_id = auth.uid() or public.is_admin());

create or replace function public.reports_fill_reporter()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  r public.user_role;
begin
  new.reporter_id := auth.uid();
  if new.reporter_id is null then
    new.reporter_role := 'visitor';
  else
    select role into r from public.profiles where id = new.reporter_id;
    new.reporter_role := case when r in ('owner', 'admin') then 'owner'::public.reporter_role
                              else 'user'::public.reporter_role end;
  end if;
  new.status := 'new';
  new.admin_note := null;
  new.created_at := now();
  return new;
end $$;

create trigger reports_fill
  before insert on public.reports
  for each row execute function public.reports_fill_reporter();

-- ---------------------------------------------------------------------------
-- Claims ("Is this your business?")
-- ---------------------------------------------------------------------------
create policy claims_select on public.claims for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
create policy claims_insert on public.claims for insert to authenticated
  with check (
    user_id = auth.uid()
    and status = 'pending'
    and admin_note is null
    and exists (select 1 from public.listings l where l.id = listing_id and l.owner_id is null)
  );

-- ---------------------------------------------------------------------------
-- Subscriptions: owner reads own; only the Stripe webhook (service role,
-- which bypasses RLS) writes.
-- ---------------------------------------------------------------------------
create policy subscriptions_select on public.subscriptions for select to authenticated
  using (owner_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- Statistics: admin reads raw rows; owners get aggregates via owner_stats().
-- ---------------------------------------------------------------------------
create policy events_admin on public.listing_events for select to authenticated using (public.is_admin());
create policy search_admin on public.search_log     for select to authenticated using (public.is_admin());
grant select on public.listing_events, public.search_log to authenticated;

-- ---------------------------------------------------------------------------
-- Push tokens
-- ---------------------------------------------------------------------------
create policy push_own on public.push_tokens for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ===== 20261126000003_functions.sql =====
-- Dalilak – 0003 functions: listing queries, user actions, admin actions,
-- statistics and premium expiry.

-- ---------------------------------------------------------------------------
-- Slugs
-- ---------------------------------------------------------------------------
create or replace function public.unique_slug(p_name text, p_city text)
returns text language plpgsql stable set search_path = '' as $$
declare
  base text := public.slugify(coalesce(p_name, '') || ' ' || coalesce(p_city, ''));
  candidate text;
  n int := 1;
begin
  if base = '' then base := 'listing'; end if;
  base := left(base, 80);
  candidate := base;
  while exists (select 1 from public.listings where slug = candidate) loop
    n := n + 1;
    candidate := base || '-' || n;
  end loop;
  return candidate;
end $$;

-- ---------------------------------------------------------------------------
-- Ranking helpers (computed columns: select=*,rating_score)
-- Bayesian average of Google rating + app reviews, so a listing with one
-- 5-star review does not beat one with 4.7 from 2000 reviews.
-- Payment never enters this score.
-- ---------------------------------------------------------------------------
create or replace function public.rating_score(l public.listings)
returns numeric language sql stable set search_path = '' as $$
  with g as (
    select coalesce(
             sum(coalesce(rating_google, 0) * reviews_google + coalesce(app_rating_avg, 0) * app_reviews_count)
             / nullif(sum(reviews_google + app_reviews_count), 0),
             4.0) as c
      from public.listings where status = 'active'
  )
  select round(
           (coalesce(l.rating_google, 0) * l.reviews_google
            + coalesce(l.app_rating_avg, 0) * l.app_reviews_count
            + g.c * 20)
           / (l.reviews_google + l.app_reviews_count + 20), 3)
    from g
$$;

-- ---------------------------------------------------------------------------
-- Search / lists
-- ---------------------------------------------------------------------------
-- Home list and search. With p_boost, active premium listings come first
-- (the UI always labels them "مميّز / Featured"); then Google rating and count.
create or replace function public.search_listings(
  q          text    default null,
  p_category text    default null,
  p_province text    default null,
  p_boost    boolean default true,
  p_limit    int     default 50,
  p_offset   int     default 0
)
returns setof public.listings
language sql stable set search_path = '' as $$
  with params as (select nullif(public.normalize_text(trim(q)), '') as nq)
  select l.*
    from public.listings l
    join public.categories c on c.slug = l.category
    cross join params p
   where l.status = 'active'
     and (p_category is null or l.category = p_category)
     and (p_province is null or l.province = p_province)
     and (p.nq is null
          or l.search_doc like '%' || p.nq || '%'
          or extensions.word_similarity(p.nq, l.search_doc) > 0.45
          or public.normalize_text(c.name_ar || ' ' || c.name_fr || ' ' || c.name_nl || ' ' || c.name_en)
               like '%' || p.nq || '%')
   order by
     case when p_boost and public.premium_active(l) then 0 else 1 end,
     case when p.nq is not null and l.search_doc like '%' || p.nq || '%' then 0 else 1 end,
     l.rating_google desc nulls last,
     l.reviews_google desc,
     l.id
   limit least(greatest(p_limit, 1), 100)
  offset greatest(p_offset, 0)
$$;

-- "الأعلى تقييماً": rating only, never payment.
create or replace function public.top_rated(
  p_category text default null,
  p_province text default null,
  p_limit    int  default 50
)
returns setof public.listings
language sql stable set search_path = '' as $$
  select l.*
    from public.listings l
   where l.status = 'active'
     and (l.reviews_google + l.app_reviews_count) > 0
     and (p_category is null or l.category = p_category)
     and (p_province is null or l.province = p_province)
   order by public.rating_score(l) desc, (l.reviews_google + l.app_reviews_count) desc, l.id
   limit least(greatest(p_limit, 1), 100)
$$;

-- "خياراتنا المفضلة": active premium only, shuffled by a seed the client
-- changes (per visit / per hour) so every premium business gets equal exposure.
create or replace function public.featured_listings(
  p_category text default null,
  p_province text default null,
  p_seed     text default null,
  p_limit    int  default 20
)
returns setof public.listings
language sql stable set search_path = '' as $$
  select l.*
    from public.listings l
   where l.status = 'active'
     and public.premium_active(l)
     and (p_category is null or l.category = p_category)
     and (p_province is null or l.province = p_province)
   order by md5(l.id::text || coalesce(p_seed, to_char(now(), 'YYYYMMDDHH24')))
   limit least(greatest(p_limit, 1), 100)
$$;

-- Visible reviews with the author's display name (profiles stay private).
create or replace function public.listing_reviews(p_listing_id bigint)
returns table (
  id bigint, stars smallint, text text, author text,
  owner_reply text, owner_replied_at timestamptz, created_at timestamptz, is_mine boolean
)
language sql stable security definer set search_path = '' as $$
  select r.id, r.stars, r.text, coalesce(p.display_name, ''), r.owner_reply, r.owner_replied_at,
         r.created_at, r.user_id = auth.uid()
    from public.reviews r
    join public.listings l on l.id = r.listing_id and l.status = 'active'
    left join public.profiles p on p.id = r.user_id
   where r.listing_id = p_listing_id and r.status = 'visible'
   order by r.created_at desc
$$;

-- ---------------------------------------------------------------------------
-- User actions
-- ---------------------------------------------------------------------------
-- "Add your business": login required, goes to pending; submitter becomes
-- the owner once the admin approves it.
create or replace function public.submit_listing(
  p_name      text,
  p_category  text,
  p_province  text,
  p_city      text,
  p_address   text,
  p_phone     text,
  p_languages text[] default '{}',
  p_website   text   default null
)
returns bigint
language plpgsql security definer set search_path = '' as $$
declare
  needs_lang boolean;
  new_id bigint;
begin
  if auth.uid() is null then
    raise exception 'login_required' using errcode = '42501';
  end if;
  select requires_languages into needs_lang from public.categories where slug = p_category;
  if not found then
    raise exception 'unknown_category';
  end if;
  if needs_lang and coalesce(array_length(p_languages, 1), 0) = 0 then
    raise exception 'languages_required';
  end if;
  if (select count(*) from public.listings
       where owner_id = auth.uid() and status = 'pending') >= 5 then
    raise exception 'too_many_pending';
  end if;

  insert into public.listings (slug, name, category, province, city, address, phone, website,
                               languages, language_verified, status, source, owner_id)
  values (public.unique_slug(p_name, p_city), trim(p_name), p_category, p_province,
          nullif(trim(p_city), ''), nullif(trim(p_address), ''), nullif(trim(p_phone), ''),
          nullif(trim(p_website), ''), coalesce(p_languages, '{}'), true, 'pending', 'owner', auth.uid())
  returning id into new_id;
  return new_id;
end $$;

-- Owner replies once to a review on their listing.
create or replace function public.reply_to_review(p_review_id bigint, p_text text)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.reviews r
     set owner_reply = left(trim(p_text), 1000), owner_replied_at = now()
   where r.id = p_review_id
     and r.owner_reply is null
     and public.owns_listing(r.listing_id);
  if not found then
    raise exception 'reply_not_allowed';
  end if;
end $$;

-- Anonymous counters (call, directions, website, share, view).
create or replace function public.track_event(p_listing_id bigint, p_kind public.event_kind)
returns void
language sql security definer set search_path = '' as $$
  insert into public.listing_events (listing_id, kind)
  select id, p_kind from public.listings where id = p_listing_id and status = 'active'
$$;

create or replace function public.log_search(q text, p_category text, p_province text, p_results int)
returns void
language sql security definer set search_path = '' as $$
  insert into public.search_log (query, category, province, results)
  values (left(nullif(trim(q), ''), 100), p_category, p_province, p_results)
$$;

-- Owner statistics (premium) or admin.
create or replace function public.owner_stats(p_listing_id bigint, p_days int default 30)
returns table (kind public.event_kind, total bigint)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (public.is_admin() or (public.owns_listing(p_listing_id) and public.listing_premium(p_listing_id))) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  return query
    select e.kind, count(*)
      from public.listing_events e
     where e.listing_id = p_listing_id
       and e.created_at > now() - make_interval(days => least(greatest(p_days, 1), 365))
     group by e.kind;
end $$;

-- ---------------------------------------------------------------------------
-- Admin actions (each checks is_admin()).
-- ---------------------------------------------------------------------------
create or replace function public.assert_admin()
returns void language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin() then
    raise exception 'admin_only' using errcode = '42501';
  end if;
end $$;

create or replace function public.admin_set_listing_status(p_listing_id bigint, p_status public.listing_status)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.listings set status = p_status where id = p_listing_id;
end $$;

-- Grant or remove premium by hand (e.g. M et Mme Falfoul, promos).
-- p_until null = no expiry.
create or replace function public.admin_set_premium(p_listing_id bigint, p_on boolean, p_until timestamptz default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.listings
     set is_premium = p_on,
         premium_until = case when p_on then p_until else null end,
         is_verified = p_on or is_verified
   where id = p_listing_id;
end $$;

create or replace function public.admin_decide_claim(p_claim_id bigint, p_approve boolean, p_note text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  c public.claims;
begin
  perform public.assert_admin();
  select * into c from public.claims where id = p_claim_id and status = 'pending' for update;
  if not found then raise exception 'claim_not_pending'; end if;

  update public.claims
     set status = case when p_approve then 'approved' else 'rejected' end::public.request_status,
         admin_note = p_note, decided_at = now()
   where id = p_claim_id;

  if p_approve then
    update public.listings set owner_id = c.user_id where id = c.listing_id;
    update public.profiles set role = 'owner' where id = c.user_id and role = 'user';
    -- other pending claims on the same listing are closed
    update public.claims set status = 'rejected', admin_note = 'listing_claimed', decided_at = now()
     where listing_id = c.listing_id and status = 'pending';
  end if;
end $$;

-- Approve a new listing from "Add your business": becomes active and the
-- submitter becomes an owner.
create or replace function public.admin_approve_listing(p_listing_id bigint)
returns void language plpgsql security definer set search_path = '' as $$
declare
  uid uuid;
begin
  perform public.assert_admin();
  update public.listings set status = 'active' where id = p_listing_id and status = 'pending'
  returning owner_id into uid;
  if uid is not null then
    update public.profiles set role = 'owner' where id = uid and role = 'user';
  end if;
end $$;

-- Owner edit requests: only these keys can ever be applied.
create or replace function public.admin_decide_edit(p_edit_id bigint, p_approve boolean, p_note text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  e public.listing_edits;
  ch jsonb;
begin
  perform public.assert_admin();
  select * into e from public.listing_edits where id = p_edit_id and status = 'pending' for update;
  if not found then raise exception 'edit_not_pending'; end if;

  if p_approve then
    ch := e.changes;
    update public.listings l set
      name        = coalesce(nullif(trim(ch ->> 'name'), ''), l.name),
      phone       = case when ch ? 'phone'   then nullif(trim(ch ->> 'phone'), '')   else l.phone   end,
      website     = case when ch ? 'website' then nullif(trim(ch ->> 'website'), '') else l.website end,
      address     = case when ch ? 'address' then nullif(trim(ch ->> 'address'), '') else l.address end,
      city        = case when ch ? 'city'    then nullif(trim(ch ->> 'city'), '')    else l.city    end,
      languages   = case when ch ? 'languages'
                         then array(select jsonb_array_elements_text(ch -> 'languages'))
                         else l.languages end,
      language_verified = case when ch ? 'languages' then true else l.language_verified end,
      description = case when jsonb_typeof(ch -> 'description') = 'object' then ch -> 'description' else l.description end,
      offer_text  = case when jsonb_typeof(ch -> 'offer_text')  = 'object' then ch -> 'offer_text'  else l.offer_text  end
    where l.id = e.listing_id;
  end if;

  update public.listing_edits
     set status = case when p_approve then 'approved' else 'rejected' end::public.request_status,
         admin_note = p_note, decided_at = now()
   where id = p_edit_id;
end $$;

create or replace function public.admin_decide_photo(p_photo_id bigint, p_approve boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare
  ph public.listing_photos;
begin
  perform public.assert_admin();
  update public.listing_photos
     set status = case when p_approve then 'approved' else 'rejected' end::public.request_status
   where id = p_photo_id
  returning * into ph;
  if not found then raise exception 'photo_not_found'; end if;
  if p_approve and ph.kind = 'logo' then
    -- one approved logo at a time
    update public.listing_photos set status = 'rejected'
     where listing_id = ph.listing_id and kind = 'logo' and status = 'approved' and id <> ph.id;
    update public.listings set logo_path = ph.storage_path where id = ph.listing_id;
  end if;
end $$;

create or replace function public.admin_set_review_status(p_review_id bigint, p_status public.review_status)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.reviews set status = p_status where id = p_review_id;
end $$;

create or replace function public.admin_update_report(p_report_id bigint, p_status public.report_status, p_note text default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.reports set status = p_status, admin_note = coalesce(p_note, admin_note) where id = p_report_id;
end $$;

-- ---------------------------------------------------------------------------
-- Premium expiry. Listings stay; only is_premium is switched off.
-- ---------------------------------------------------------------------------
create or replace function public.expire_premium()
returns int language plpgsql security definer set search_path = '' as $$
declare
  n int;
begin
  update public.listings
     set is_premium = false
   where is_premium and premium_until is not null and premium_until < now() - interval '1 day';
  get diagnostics n = row_count;
  return n;
end $$;

-- Run it daily with pg_cron when available (it is on Supabase).
-- If pg_cron cannot be enabled here, enable it in Dashboard → Integrations → Cron
-- and run the cron.schedule line by hand.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    execute $cron$ select cron.schedule('dalilak-expire-premium', '17 3 * * *', 'select public.expire_premium()') $cron$;
  end if;
exception when others then
  raise notice 'pg_cron not scheduled: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------------
-- First admin. Run once in the Supabase SQL editor after signing up:
--   select public.bootstrap_admin('you@example.com');
-- It also links listing 1 (M et Mme Falfoul) to that account.
-- ---------------------------------------------------------------------------
create or replace function public.bootstrap_admin(p_email text)
returns text language plpgsql security definer set search_path = '' as $$
declare
  uid uuid;
begin
  select id into uid from auth.users where lower(email) = lower(trim(p_email));
  if uid is null then
    raise exception 'no user with this email – sign up first';
  end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  update public.profiles set role = 'admin' where id = uid;
  update public.listings set owner_id = uid where id = 1;
  return 'ok: ' || uid::text;
end $$;

-- ---------------------------------------------------------------------------
-- Execute rights. Supabase grants EXECUTE to PUBLIC by default; close that
-- and open only what the app calls.
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;

grant execute on function
  public.normalize_text(text), public.slugify(text),
  public.premium_active(public.listings), public.rating_score(public.listings),
  public.search_listings(text, text, text, boolean, int, int),
  public.top_rated(text, text, int),
  public.featured_listings(text, text, text, int),
  public.listing_reviews(bigint),
  public.track_event(bigint, public.event_kind),
  public.log_search(text, text, text, int),
  -- used inside RLS policies, so callers need execute on them
  public.is_admin(), public.owns_listing(bigint), public.listing_premium(bigint)
to anon, authenticated;

grant execute on function
  public.submit_listing(text, text, text, text, text, text, text[], text),
  public.reply_to_review(bigint, text),
  public.owner_stats(bigint, int),
  public.admin_set_listing_status(bigint, public.listing_status),
  public.admin_set_premium(bigint, boolean, timestamptz),
  public.admin_decide_claim(bigint, boolean, text),
  public.admin_approve_listing(bigint),
  public.admin_decide_edit(bigint, boolean, text),
  public.admin_decide_photo(bigint, boolean),
  public.admin_set_review_status(bigint, public.review_status),
  public.admin_update_report(bigint, public.report_status, text)
to authenticated;
-- bootstrap_admin, expire_premium, unique_slug: postgres / service_role only.

-- ===== 20261126000004_storage.sql =====
-- Dalilak – 0004 storage: bucket for premium logos and gallery photos.
-- Path layout: listing-photos/<listing_id>/<file>.webp  (public read, max 3 MB)

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('listing-photos', 'listing-photos', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create or replace function public.path_listing_id(p_name text)
returns bigint language sql immutable set search_path = '' as $$
  select case when split_part(p_name, '/', 1) ~ '^[0-9]{1,18}$'
              then split_part(p_name, '/', 1)::bigint end
$$;
grant execute on function public.path_listing_id(text) to authenticated;

create policy "premium owner uploads photos"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'listing-photos'
    and public.owns_listing(public.path_listing_id(name))
    and public.listing_premium(public.path_listing_id(name))
  );

create policy "owner or admin deletes photos"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'listing-photos'
    and (public.owns_listing(public.path_listing_id(name)) or public.is_admin())
  );

