-- ===== 20261126000006_admin_tools.sql =====
-- Dalilak – 0006 admin tools: create/edit listings, logo and photos, from the admin panel.
-- Run once in the Supabase SQL editor on the existing project (safe to re-run).

-- ---------------------------------------------------------------------------
-- Create a listing (active straight away, source 'admin'). Returns the new id.
-- ---------------------------------------------------------------------------
create or replace function public.admin_create_listing(p jsonb)
returns bigint language plpgsql security definer set search_path = '' as $$
declare
  new_id bigint;
begin
  perform public.assert_admin();
  insert into public.listings (slug, name, category, type_label, province, city, address, phone, website,
                               languages, language_verified, status, source, description, offer_text)
  values (
    public.unique_slug(p ->> 'name', p ->> 'city'),
    trim(p ->> 'name'),
    p ->> 'category',
    nullif(trim(p ->> 'type_label'), ''),
    p ->> 'province',
    nullif(trim(p ->> 'city'), ''),
    nullif(trim(p ->> 'address'), ''),
    nullif(trim(p ->> 'phone'), ''),
    nullif(trim(p ->> 'website'), ''),
    coalesce(array(select jsonb_array_elements_text(p -> 'languages')), '{}'),
    coalesce((p ->> 'language_verified')::boolean, true),
    coalesce((p ->> 'status')::public.listing_status, 'active'),
    'admin',
    case when jsonb_typeof(p -> 'description') = 'object' then p -> 'description' else '{}'::jsonb end,
    case when jsonb_typeof(p -> 'offer_text')  = 'object' then p -> 'offer_text'  else '{}'::jsonb end
  )
  returning id into new_id;
  return new_id;
end $$;

-- ---------------------------------------------------------------------------
-- Edit a listing. Only keys present in p are changed. The URL (slug) never
-- changes, so links and Google stay valid when a name is corrected.
-- Featured is changed with admin_set_premium().
-- ---------------------------------------------------------------------------
create or replace function public.admin_update_listing(p_id bigint, p jsonb)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.listings l set
    name              = case when p ? 'name'       then trim(p ->> 'name') else l.name end,
    category          = case when p ? 'category'   then p ->> 'category' else l.category end,
    type_label        = case when p ? 'type_label' then nullif(trim(p ->> 'type_label'), '') else l.type_label end,
    province          = case when p ? 'province'   then p ->> 'province' else l.province end,
    city              = case when p ? 'city'       then nullif(trim(p ->> 'city'), '') else l.city end,
    address           = case when p ? 'address'    then nullif(trim(p ->> 'address'), '') else l.address end,
    phone             = case when p ? 'phone'      then nullif(trim(p ->> 'phone'), '') else l.phone end,
    website           = case when p ? 'website'    then nullif(trim(p ->> 'website'), '') else l.website end,
    languages         = case when p ? 'languages'  then coalesce(array(select jsonb_array_elements_text(p -> 'languages')), '{}') else l.languages end,
    language_verified = case when p ? 'language_verified' then (p ->> 'language_verified')::boolean else l.language_verified end,
    status            = case when p ? 'status'     then (p ->> 'status')::public.listing_status else l.status end,
    is_verified       = case when p ? 'is_verified' then (p ->> 'is_verified')::boolean else l.is_verified end,
    description       = case when jsonb_typeof(p -> 'description') = 'object' then p -> 'description' else l.description end,
    offer_text        = case when jsonb_typeof(p -> 'offer_text')  = 'object' then p -> 'offer_text'  else l.offer_text  end
  where l.id = p_id;
  if not found then raise exception 'listing_not_found'; end if;
end $$;

-- ---------------------------------------------------------------------------
-- Photos added by the admin are approved immediately.
-- A new logo replaces the old one; the old file paths are returned so the
-- panel can delete them from storage.
-- ---------------------------------------------------------------------------
create or replace function public.admin_add_photo(p_listing_id bigint, p_kind public.photo_kind, p_path text)
returns text[] language plpgsql security definer set search_path = '' as $$
declare
  old_paths text[] := '{}';
  next_order int;
begin
  perform public.assert_admin();
  if public.path_listing_id(p_path) is distinct from p_listing_id then
    raise exception 'path_must_start_with_listing_id';
  end if;
  if p_kind = 'logo' then
    with gone as (
      delete from public.listing_photos where listing_id = p_listing_id and kind = 'logo' returning storage_path
    ) select coalesce(array_agg(storage_path), '{}') into old_paths from gone;
  end if;
  select coalesce(max(sort_order), 0) + 1 into next_order
    from public.listing_photos where listing_id = p_listing_id and kind = p_kind;
  insert into public.listing_photos (listing_id, kind, storage_path, sort_order, status)
  values (p_listing_id, p_kind, p_path, next_order, 'approved');
  if p_kind = 'logo' then
    update public.listings set logo_path = p_path where id = p_listing_id;
  end if;
  return old_paths;
end $$;

-- Removes the photo row and returns its storage path (the panel deletes the file).
create or replace function public.admin_delete_photo(p_photo_id bigint)
returns text language plpgsql security definer set search_path = '' as $$
declare
  ph public.listing_photos;
begin
  perform public.assert_admin();
  delete from public.listing_photos where id = p_photo_id returning * into ph;
  if not found then raise exception 'photo_not_found'; end if;
  if ph.kind = 'logo' then
    update public.listings set logo_path = null where id = ph.listing_id and logo_path = ph.storage_path;
  end if;
  return ph.storage_path;
end $$;

-- Admin may upload into any listing folder of the bucket (deleting was already allowed).
drop policy if exists "admin uploads photos" on storage.objects;
create policy "admin uploads photos"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'listing-photos'
    and public.is_admin()
    and public.path_listing_id(name) is not null
  );

revoke execute on function
  public.admin_create_listing(jsonb),
  public.admin_update_listing(bigint, jsonb),
  public.admin_add_photo(bigint, public.photo_kind, text),
  public.admin_delete_photo(bigint)
from public, anon;

grant execute on function
  public.admin_create_listing(jsonb),
  public.admin_update_listing(bigint, jsonb),
  public.admin_add_photo(bigint, public.photo_kind, text),
  public.admin_delete_photo(bigint)
to authenticated;

-- ===== 20261126000007_marketplace.sql =====
-- Dalilak – 0007 Buy & Sell ("بيع وشراء").
-- Ads are created only by the admin. Buyers contact Yousef (WhatsApp), never the seller,
-- so seller details and the commission live in a separate admin-only table.
-- Run once in the Supabase SQL editor on the existing project.

create type public.ad_category as enum ('business', 'real_estate', 'cars', 'furniture', 'other');
create type public.ad_status   as enum ('active', 'sold', 'hidden');

create table public.ads (
  id          bigint generated always as identity primary key,
  slug        text unique,                      -- "<id>-<latin title>", set on insert
  title       text not null check (char_length(title) between 2 and 140),
  category    public.ad_category not null,
  city        text not null check (char_length(city) between 1 and 80),
  price_eur   numeric(12, 2) check (price_eur >= 0),   -- null = "price on request"
  description text not null default '' check (char_length(description) <= 5000),
  status      public.ad_status not null default 'active',
  cover_path  text,                             -- first photo, kept in sync by the photo functions
  sold_at     timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index on public.ads (status, category, created_at desc);
create trigger ads_touch before update on public.ads for each row execute function public.touch_updated_at();

-- Admin-only: who sells, the commission, notes. Never readable by the public.
create table public.ads_private (
  ad_id        bigint primary key references public.ads on delete cascade,
  commission   text check (char_length(commission) <= 200),
  seller_name  text check (char_length(seller_name) <= 120),
  seller_phone text check (char_length(seller_phone) <= 40),
  notes        text check (char_length(notes) <= 2000)
);

create table public.ad_photos (
  id           bigint generated always as identity primary key,
  ad_id        bigint not null references public.ads on delete cascade,
  storage_path text not null unique,
  sort_order   int not null default 0,
  created_at   timestamptz not null default now()
);
create index on public.ad_photos (ad_id, sort_order);

create or replace function public.check_ad_photo_limit()
returns trigger language plpgsql set search_path = '' as $$
begin
  if (select count(*) from public.ad_photos where ad_id = new.ad_id) >= 8 then
    raise exception 'photo_limit: max 8 photos per ad' using errcode = 'check_violation';
  end if;
  return new;
end $$;
create trigger ad_photos_limit before insert on public.ad_photos for each row execute function public.check_ad_photo_limit();

-- ---------------------------------------------------------------------------
-- RLS: the public sees active and sold ads (and their photos); admin sees all.
-- ---------------------------------------------------------------------------
revoke all on public.ads, public.ads_private, public.ad_photos from anon, authenticated;
grant select on public.ads, public.ad_photos to anon, authenticated;
grant select on public.ads_private to authenticated;   -- admin only (RLS)

alter table public.ads         enable row level security;
alter table public.ads_private enable row level security;
alter table public.ad_photos   enable row level security;

create policy ads_select on public.ads for select
  using (status in ('active', 'sold') or public.is_admin());
create policy ads_private_admin on public.ads_private for select to authenticated
  using (public.is_admin());
create policy ad_photos_select on public.ad_photos for select
  using (exists (select 1 from public.ads a where a.id = ad_id and (a.status in ('active', 'sold') or public.is_admin())));

-- ---------------------------------------------------------------------------
-- Admin functions
-- ---------------------------------------------------------------------------
-- Create (p_id null) or update an ad, including its private fields. Returns the id.
create or replace function public.admin_save_ad(p_id bigint, p jsonb)
returns bigint language plpgsql security definer set search_path = '' as $$
declare
  v_id bigint := p_id;
  st public.ad_status := coalesce((p ->> 'status')::public.ad_status, 'active');
  price numeric := nullif(trim(coalesce(p ->> 'price_eur', '')), '')::numeric;
begin
  perform public.assert_admin();
  if v_id is null then
    insert into public.ads (title, category, city, price_eur, description, status, sold_at)
    values (trim(p ->> 'title'), (p ->> 'category')::public.ad_category, trim(p ->> 'city'), price,
            coalesce(p ->> 'description', ''), st, case when st = 'sold' then now() end)
    returning id into v_id;
    update public.ads
       set slug = v_id::text || coalesce('-' || nullif(left(public.slugify(p ->> 'title'), 60), ''), '')
     where id = v_id;
  else
    update public.ads set
      title = trim(p ->> 'title'),
      category = (p ->> 'category')::public.ad_category,
      city = trim(p ->> 'city'),
      price_eur = price,
      description = coalesce(p ->> 'description', ''),
      sold_at = case when st = 'sold' then coalesce(sold_at, now()) else null end,
      status = st
    where id = v_id;
    if not found then raise exception 'ad_not_found'; end if;
  end if;

  insert into public.ads_private (ad_id, commission, seller_name, seller_phone, notes)
  values (v_id, nullif(trim(p ->> 'commission'), ''), nullif(trim(p ->> 'seller_name'), ''),
          nullif(trim(p ->> 'seller_phone'), ''), nullif(trim(p ->> 'notes'), ''))
  on conflict (ad_id) do update set
    commission = excluded.commission, seller_name = excluded.seller_name,
    seller_phone = excluded.seller_phone, notes = excluded.notes;
  return v_id;
end $$;

create or replace function public.admin_set_ad_status(p_id bigint, p_status public.ad_status)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_admin();
  update public.ads
     set status = p_status,
         sold_at = case when p_status = 'sold' then coalesce(sold_at, now()) else null end
   where id = p_id;
end $$;

create or replace function public.refresh_ad_cover(p_ad_id bigint)
returns void language sql security definer set search_path = '' as $$
  update public.ads
     set cover_path = (select storage_path from public.ad_photos where ad_id = p_ad_id order by sort_order, id limit 1)
   where id = p_ad_id
$$;

create or replace function public.admin_add_ad_photo(p_ad_id bigint, p_path text)
returns bigint language plpgsql security definer set search_path = '' as $$
declare
  new_id bigint;
begin
  perform public.assert_admin();
  if public.path_listing_id(p_path) is distinct from p_ad_id then
    raise exception 'path_must_start_with_ad_id';
  end if;
  insert into public.ad_photos (ad_id, storage_path, sort_order)
  values (p_ad_id, p_path, (select coalesce(max(sort_order), 0) + 1 from public.ad_photos where ad_id = p_ad_id))
  returning id into new_id;
  perform public.refresh_ad_cover(p_ad_id);
  return new_id;
end $$;

create or replace function public.admin_delete_ad_photo(p_photo_id bigint)
returns text language plpgsql security definer set search_path = '' as $$
declare
  ph public.ad_photos;
begin
  perform public.assert_admin();
  delete from public.ad_photos where id = p_photo_id returning * into ph;
  if not found then raise exception 'photo_not_found'; end if;
  perform public.refresh_ad_cover(ph.ad_id);
  return ph.storage_path;
end $$;

-- Make one photo the cover (moves it to the front).
create or replace function public.admin_set_ad_cover(p_photo_id bigint)
returns void language plpgsql security definer set search_path = '' as $$
declare
  ph public.ad_photos;
begin
  perform public.assert_admin();
  select * into ph from public.ad_photos where id = p_photo_id;
  if not found then raise exception 'photo_not_found'; end if;
  update public.ad_photos set sort_order = (select coalesce(min(sort_order), 0) - 1 from public.ad_photos where ad_id = ph.ad_id)
   where id = p_photo_id;
  perform public.refresh_ad_cover(ph.ad_id);
end $$;

revoke execute on function
  public.admin_save_ad(bigint, jsonb), public.admin_set_ad_status(bigint, public.ad_status),
  public.refresh_ad_cover(bigint), public.admin_add_ad_photo(bigint, text),
  public.admin_delete_ad_photo(bigint), public.admin_set_ad_cover(bigint),
  public.check_ad_photo_limit()
from public, anon, authenticated;

grant execute on function
  public.admin_save_ad(bigint, jsonb), public.admin_set_ad_status(bigint, public.ad_status),
  public.admin_add_ad_photo(bigint, text), public.admin_delete_ad_photo(bigint), public.admin_set_ad_cover(bigint)
to authenticated;

-- ---------------------------------------------------------------------------
-- Storage: public bucket for ad photos (path "<ad_id>/<file>"), admin writes.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('ad-photos', 'ad-photos', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "admin uploads ad photos"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'ad-photos' and public.is_admin() and public.path_listing_id(name) is not null);

create policy "admin deletes ad photos"
  on storage.objects for delete to authenticated
  using (bucket_id = 'ad-photos' and public.is_admin());

-- ===== 20261126000008_banners.sql =====
-- Dalilak – 0008 paid banner ads ("إعلاناتكم").
-- Banners are created only by the admin. A banner is public only while it is visible and
-- today (Brussels time) is between its start and end dates, so it hides itself after the end date.
-- Advertiser name, price and notes live in an admin-only table.
-- Run once in the Supabase SQL editor on the existing project.

create table public.banners (
  id         bigint generated always as identity primary key,
  title      text not null check (char_length(title) between 2 and 120),
  image_path text,                                  -- storage path in bucket "banners"
  link_url   text check (link_url is null or link_url ~* '^https://'),
  starts_on  date,                                  -- null = from now
  ends_on    date,                                  -- null = no end
  is_visible boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_on is null or starts_on is null or ends_on >= starts_on)
);
create trigger banners_touch before update on public.banners for each row execute function public.touch_updated_at();

create table public.banners_private (
  banner_id       bigint primary key references public.banners on delete cascade,
  advertiser_name text check (char_length(advertiser_name) <= 120),
  price_paid      text check (char_length(price_paid) <= 100),
  notes           text check (char_length(notes) <= 2000)
);

-- Today in Belgium (banners switch at local midnight, not UTC).
create or replace function public.today_brussels()
returns date language sql stable set search_path = '' as $$
  select (now() at time zone 'Europe/Brussels')::date
$$;

revoke all on public.banners, public.banners_private from anon, authenticated;
grant select on public.banners to anon, authenticated;
grant select on public.banners_private to authenticated;   -- admin only (RLS)

alter table public.banners         enable row level security;
alter table public.banners_private enable row level security;

create policy banners_select on public.banners for select
  using (
    (is_visible
     and image_path is not null
     and (starts_on is null or starts_on <= public.today_brussels())
     and (ends_on is null or ends_on >= public.today_brussels()))
    or public.is_admin()
  );
create policy banners_private_admin on public.banners_private for select to authenticated
  using (public.is_admin());

-- Create (p_id null) or update a banner and its private fields. Returns the id.
create or replace function public.admin_save_banner(p_id bigint, p jsonb)
returns bigint language plpgsql security definer set search_path = '' as $$
declare
  v_id bigint := p_id;
begin
  perform public.assert_admin();
  if v_id is null then
    insert into public.banners (title, link_url, starts_on, ends_on, is_visible, sort_order)
    values (trim(p ->> 'title'), nullif(trim(p ->> 'link_url'), ''),
            nullif(p ->> 'starts_on', '')::date, nullif(p ->> 'ends_on', '')::date,
            coalesce((p ->> 'is_visible')::boolean, true), coalesce(nullif(p ->> 'sort_order', '')::int, 0))
    returning id into v_id;
  else
    update public.banners set
      title = trim(p ->> 'title'),
      link_url = nullif(trim(p ->> 'link_url'), ''),
      starts_on = nullif(p ->> 'starts_on', '')::date,
      ends_on = nullif(p ->> 'ends_on', '')::date,
      is_visible = coalesce((p ->> 'is_visible')::boolean, is_visible),
      sort_order = coalesce(nullif(p ->> 'sort_order', '')::int, sort_order)
    where id = v_id;
    if not found then raise exception 'banner_not_found'; end if;
  end if;

  insert into public.banners_private (banner_id, advertiser_name, price_paid, notes)
  values (v_id, nullif(trim(p ->> 'advertiser_name'), ''), nullif(trim(p ->> 'price_paid'), ''), nullif(trim(p ->> 'notes'), ''))
  on conflict (banner_id) do update set
    advertiser_name = excluded.advertiser_name, price_paid = excluded.price_paid, notes = excluded.notes;
  return v_id;
end $$;

-- Set the banner image; returns the previous path so the panel can delete that file.
create or replace function public.admin_set_banner_image(p_id bigint, p_path text)
returns text language plpgsql security definer set search_path = '' as $$
declare
  old_path text;
begin
  perform public.assert_admin();
  if public.path_listing_id(p_path) is distinct from p_id then
    raise exception 'path_must_start_with_banner_id';
  end if;
  select image_path into old_path from public.banners where id = p_id for update;
  if not found then raise exception 'banner_not_found'; end if;
  update public.banners set image_path = p_path where id = p_id;
  return old_path;
end $$;

revoke execute on function public.admin_save_banner(bigint, jsonb), public.admin_set_banner_image(bigint, text)
  from public, anon, authenticated;
grant execute on function public.admin_save_banner(bigint, jsonb), public.admin_set_banner_image(bigint, text)
  to authenticated;
grant execute on function public.today_brussels() to anon, authenticated;

-- Storage: public bucket "banners" (path "<banner_id>/<file>"), admin writes.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('banners', 'banners', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "admin uploads banners"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'banners' and public.is_admin() and public.path_listing_id(name) is not null);

create policy "admin deletes banners"
  on storage.objects for delete to authenticated
  using (bucket_id = 'banners' and public.is_admin());

-- ===== 20261127000009_category_shipping.sql =====
-- Dalilak – 0009 new category "Shipping & Furniture Moving" (شحن ونقل أثاث).
-- Existing categories and listings are not changed. Safe to run more than once.
insert into public.categories (slug, name_ar, name_fr, name_nl, name_en, icon, sort_order, requires_languages)
values ('shipping', 'شحن ونقل أثاث', 'Expédition et déménagement', 'Verzending en verhuizing', 'Shipping & Furniture Moving', '🚚', 9, false)
on conflict (slug) do update set
  name_ar = excluded.name_ar, name_fr = excluded.name_fr, name_nl = excluded.name_nl, name_en = excluded.name_en,
